SELECT 'gongkao', '会议活动类', 'kp-ms-org-meeting', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "计划组织：会议活动类"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "千万不要报流水账（定场地、买矿泉水）！考官要听的是如何把控会议的核心环节。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、会议的高分亮点"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "所有考生都会背“事前准备、事中组织、事后总结”。如何脱颖而出？重点写【事中】的亮点！"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "如果是听证会：重点说如何保证各方代表发言时间的公平性，遇到双方激烈争吵时主持人如何控场引导。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "如果是表彰大会：重点说如何深挖先进事迹，通过播放纪录片、邀请家属上台等形式，激发全体员工的情感共鸣。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "如果是研讨会：重点说如何将大家提出的天马行空的想法，由专家组进行可行性论证，最终形成一套可落地的方案。"}]}]}]}]}$$ AS jsonb), NULL, '会议活动类的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "计划组织", "会议"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_org_meeting", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
